import{_ as e,o,c as r,l as n,t as s,N as a}from"./chunks/framework.CMqbtke2.js";const b=JSON.parse('{"title":"install | x-cmd man (man1) | copy files and set attributes","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | install - copy files and set attributes","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"install | x-cmd man (man1) | copy files and set attributes"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | install - copy files and set attributes"}]]},"headers":[],"params":{"isMan":true,"man":"install","category":"man1","desc":"copy files and set attributes"},"relativePath":"man1/install.md","filePath":"man1/install.md"}'),d={name:"man1/install.md"},i={class:"visually-hidden"},l=a('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>install - copy files and set attributes</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>install</strong> [<em>OPTION</em>]... [<em>-T</em>] <em>SOURCE DEST</em> <br> <strong>install</strong> [<em>OPTION</em>]... <em>SOURCE</em>... <em>DIRECTORY</em> <br> <strong>install</strong> [<em>OPTION</em>]... <em>-t DIRECTORY SOURCE</em>... <br> <strong>install</strong> [<em>OPTION</em>]... <em>-d DIRECTORY</em>...</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>This install program copies files (often just compiled) into destination locations you choose. If you want to download and install a ready-to-use package on a GNU/Linux system, you should instead be using a package manager like <strong>yum</strong>(1) or <strong>apt-get</strong>(1).</p><p>In the first three forms, copy SOURCE to DEST or multiple SOURCE(s) to the existing DIRECTORY, while setting permission modes and owner/group. In the 4th form, create all components of the given DIRECTORY(ies).</p><p>Mandatory arguments to long options are mandatory for short options too.</p><dl><dt><strong>--backup</strong>[=<em>CONTROL</em>]</dt><dd>make a backup of each existing destination file</dd><dt><strong>-b</strong></dt><dd>like <strong>--backup</strong> but does not accept an argument</dd><dt><strong>-c</strong></dt><dd>(ignored)</dd><dt><strong>-C</strong>, <strong>--compare</strong></dt><dd>compare content of source and destination files, and if no change to content, ownership, and permissions, do not modify the destination at all</dd><dt><strong>-d</strong>, <strong>--directory</strong></dt><dd>treat all arguments as directory names; create all components of the specified directories</dd><dt><strong>-D</strong></dt><dd>create all leading components of DEST except the last, or all components of <strong>--target-directory</strong>, then copy SOURCE to DEST</dd><dt><strong>--debug</strong></dt><dd>explain how a file is copied. Implies <strong>-v</strong></dd><dt><strong>-g</strong>, <strong>--group</strong>=<em>GROUP</em></dt><dd>set group ownership, instead of process&#39; current group</dd><dt><strong>-m</strong>, <strong>--mode</strong>=<em>MODE</em></dt><dd>set permission mode (as in chmod), instead of rwxr-xr-x</dd><dt><strong>-o</strong>, <strong>--owner</strong>=<em>OWNER</em></dt><dd>set ownership (super-user only)</dd><dt><strong>-p</strong>, <strong>--preserve-timestamps</strong></dt><dd>apply access/modification times of SOURCE files to corresponding destination files</dd><dt><strong>-s</strong>, <strong>--strip</strong></dt><dd>strip symbol tables</dd><dt><strong>--strip-program</strong>=<em>PROGRAM</em></dt><dd>program used to strip binaries</dd><dt><strong>-S</strong>, <strong>--suffix</strong>=<em>SUFFIX</em></dt><dd>override the usual backup suffix</dd><dt><strong>-t</strong>, <strong>--target-directory</strong>=<em>DIRECTORY</em></dt><dd>copy all SOURCE arguments into DIRECTORY</dd><dt><strong>-T</strong>, <strong>--no-target-directory</strong></dt><dd>treat DEST as a normal file</dd><dt><strong>-v</strong>, <strong>--verbose</strong></dt><dd>print the name of each created file or directory</dd><dt><strong>--preserve-context</strong></dt><dd>preserve SELinux security context</dd><dt><strong>-Z</strong></dt><dd>set SELinux security context of destination file and each created directory to default type</dd><dt><strong>--context</strong>[=<em>CTX</em>]</dt><dd>like <strong>-Z</strong>, or if CTX is specified then set the SELinux or SMACK security context to CTX</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><p>The backup suffix is &#39;~&#39;, unless set with <strong>--suffix</strong> or SIMPLE_BACKUP_SUFFIX. The version control method may be selected via the <strong>--backup</strong> option or through the VERSION_CONTROL environment variable. Here are the values:</p><dl><dt>none, off</dt><dd>never make backups (even if <strong>--backup</strong> is given)</dd><dt>numbered, t</dt><dd>make numbered backups</dd><dt>existing, nil</dt><dd>numbered if numbered backups exist, simple otherwise</dd><dt>simple, never</dt><dd>always make simple backups</dd></dl><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by David MacKenzie.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>cp</strong>(1)</p><p><br> Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/install%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/install\\</a>&gt; <br> or available locally via: info &#39;(coreutils) install invocation&#39;</p>',20);function g(t,p,c,m,h,u){return o(),r("div",null,[n("h1",i,s(t.$params.man),1),l])}const y=e(d,[["render",g]]);export{b as __pageData,y as default};
